            modelBuilder.Entity("SleepyDuck.Api.Models.ScenarioCard", b =>
                {
                    b.Property<Guid>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("uuid");

                    b.Property<string>("Category")
                        .IsRequired()
                        .HasMaxLength(50)
                        .HasColumnType("character varying(50)");

                    b.Property<string>("ProblemStatement")
                        .IsRequired()
                        .HasColumnType("text");

                    b.Property<string>("TechnicalExplanation")
                        .IsRequired()
                        .HasColumnType("text");

                    b.Property<string>("Title")
                        .IsRequired()
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)");

                    b.HasKey("Id");

                    b.HasIndex("Category");

                    b.ToTable("ScenarioCards");

                    b.HasData(
                        new
                        {
                            Id = new Guid("dae9de1c-e49c-7472-ff3b-d6588e82961d"),
                            Category = "EmailDelivery",
                            ProblemStatement = "Priya in Finance says invoices from a supplier at billing@northwind-supply.example have stopped reaching her. Internal email works, and she has checked her Junk Email folder. The supplier received no bounce message.",
                            TechnicalExplanation = "Message trace is the starting point for any 'where did my email go?' ticket because it shows what Exchange Online actually did with the message. A Quarantined status means Microsoft Defender for Office 365 or Exchange Online Protection held the message before it reached the mailbox, which is why it was not in Junk and why the sender got no bounce. After releasing it, report the false positive through Submissions and let Microsoft create the Tenant Allow/Block List entry. That keeps the exception narrow and time-limited, whereas a domain on the anti-spam allowed list skips spam filtering for anyone spoofing that domain.",
                            Title = "External emails never arrive"
                        },
                        new
                        {
                            Id = new Guid("6f67ae98-4a03-2943-e2d3-cd7ab58e559a"),
                            Category = "EmailDelivery",
                            ProblemStatement = "Marco, a contractor manager, set an inbox rule to forward project mail to a partner's external address. Every forwarded message now bounces, and the bounce message includes the code 5.7.520.",
                            TechnicalExplanation = "NDR 5.7.520 means 'Access denied, your organization does not allow external forwarding'. Automatic external forwarding is controlled by the outbound spam filter policy, whose default setting (Automatic - System-controlled) behaves as Off. Attackers often use forwarding rules to exfiltrate mail from compromised mailboxes, so leave the Default policy alone and enable forwarding only through a custom policy scoped to the people with an approved business need. Check any remote domain settings as well, because they can also stop automatic forwarding.",
                            Title = "Auto-forward bounces with 5.7.520"
                        },
                        new
                        {
                            Id = new Guid("cbe103d6-0767-bf3e-c7c5-4d18dd6f4d37"),
                            Category = "UserLicenseManagement",
                            ProblemStatement = "Dana joins the Warehouse team on Monday. They need a Microsoft 365 E3 license, but HR policy says warehouse staff shouldn't have access to SharePoint or Viva Engage.",
                            TechnicalExplanation = "A Microsoft 365 license bundles many service plans, and each plan can be switched off individually. Usage location must be set first because Microsoft needs it to determine which services are available in a country or region. Turning off apps in the license removes the entitlement to those services while leaving the rest of the E3 subscription intact. Conditional Access solves a different problem, since it controls whether a sign-in is allowed and doesn't change what the user is licensed for.",
                            Title = "New hire on E3 with restricted apps"
                        },
                        new
                        {
                            Id = new Guid("f89d8adf-76a1-3564-5e6d-4c663173c0ae"),
                            Category = "UserLicenseManagement",
                            ProblemStatement = "The 50-person Marketing department needs E3 without Viva Engage. People join and leave constantly, and assigning licenses by hand has been causing mistakes. After you make the change, a few users show a licensing error.",
                            TechnicalExplanation = "Group-based licensing in Microsoft Entra ID assigns a license to every member of a group, so a dynamic or well-managed group handles joiners and leavers automatically. Each group assignment can also disable service plans. Group-based licensing requires Microsoft Entra ID P1, which Microsoft 365 E3 includes. Assignment errors don't stop the rest of the group from being processed. They appear per user on the group's license page, and the most common causes are a missing usage location, not enough available licenses, and conflicting service plans.",
                            Title = "Licensing a whole department at scale"
                        },
                        new
                        {
                            Id = new Guid("622dd8dc-4aac-6e2b-3835-08d9f45e45dc"),
                            Category = "GroupManagement",
                            ProblemStatement = "The Events team asks for 'a group'. They want a shared email address, a shared calendar, a place to store files, and a task board. Some partners outside the company also need to be able to email the address.",
                            TechnicalExplanation = "A distribution list only delivers email to its members. A Microsoft 365 Group provisions a set of connected resources, including a group mailbox, calendar, SharePoint team site, and Planner plan, so it matches a team that collaborates. Microsoft 365 Groups don't accept mail from outside the organization by default, so this setting has to be turned on when external senders need to reach the group. Choosing a type up front matters, since it determines which workloads the team can use.",
                            Title = "Microsoft 365 Group or Distribution List?"
                        },
                        new
                        {
                            Id = new Guid("b7e23b93-9bda-3eb6-bbc5-3c556368b7c5"),
                            Category = "GroupManagement",
                            ProblemStatement = "Team lead Aisha needs to reply to customers as support@contoso.example, which is a distribution list. Customers must see only the support address, with no mention of Aisha.",
                            TechnicalExplanation = "Send As makes a message appear to come directly from the group, while Send on Behalf shows 'Aisha on behalf of Support'. Exchange handles the two differently. Send As is a recipient permission granted through the group's delegates in the Exchange admin center or with Add-RecipientPermission. Send on Behalf is set with the GrantSendOnBehalfTo parameter, using Set-DistributionGroup for distribution lists or Set-UnifiedGroup for Microsoft 365 Groups. Permission changes aren't instant, so allow time for replication before testing. Aisha must also pick the address in the From field in Outlook.",
                            Title = "Sending as the support distribution list"
                        },
                        new
                        {
                            Id = new Guid("b380cf20-1ffe-0fef-51f6-1dbccd700a3a"),
                            Category = "MailFlowRules",
                            ProblemStatement = "After a phishing incident, Security wants a warning added to the bottom of every email that comes from outside the company, stating that the message originated externally.",
                            TechnicalExplanation = "Mail flow rules (transport rules) have conditions, actions, and exceptions, and Exchange Online evaluates them as messages pass through the transport pipeline. The condition 'The sender is located > Outside the organization' targets inbound external mail. The action 'Apply a disclaimer to the message > append a disclaimer' adds the text to the bottom of the message, while 'prepend' places it at the top. The fallback option decides what happens if the disclaimer can't be inserted, such as for an encrypted message: Wrap creates a new message with the original attached, Ignore delivers it without the disclaimer, and Reject bounces it. Running the rule in test mode first lets you check what it matches without affecting live mail.",
                            Title = "Append an external sender disclaimer"
                        },
                        new
                        {
                            Id = new Guid("6b1529d8-0a15-c1cd-a50b-dad56cd70d27"),
                            Category = "MailFlowRules",
                            ProblemStatement = "Your external disclaimer rule worked for weeks, but now emails from one vendor, vendor.example, arrive with no disclaimer. Other external mail is unaffected.",
                            TechnicalExplanation = "Exchange Online evaluates mail flow rules in priority order, with 0 as the highest priority. If a matching rule has 'Stop processing more rules' turned on, later rules don't run for that message. This is a common cause of a rule that works for most mail but not for a specific sender. Message trace details list the rules that a message matched, so they show what actually happened, rather than what the rule list suggests should have happened. The safest fix is to move the disclaimer rule above the other rule, or to turn off the stop setting if it's no longer needed.",
                            Title = "Disclaimer rule skips some messages"
                        });
                });

